-- A meeting's transcription default comes from its Space (generated by
-- drizzle-kit, then completed by hand).
--
-- Until now a meeting began transcribed or not by the account setting of
-- whoever started it, so one shared Space's meetings changed with who arrived
-- first. The glossary's rule is that meeting defaults come from the Space.
--
-- A personal Space keeps what its owner chose, since its owner starts its
-- meetings. A shared Space begins on, as every meeting did before the account
-- setting existed; its admins can change it in the Space's settings.
-- users.transcribe_meetings is no longer read, and is dropped next release:
-- the code still serving while this runs reads it.
ALTER TABLE `spaces` ADD `transcribe_meetings` integer DEFAULT true NOT NULL;--> statement-breakpoint
UPDATE `spaces` SET `transcribe_meetings` = (
	SELECT `users`.`transcribe_meetings` FROM `users` WHERE `users`.`id` = `spaces`.`owner_user_id`
) WHERE `kind` = 'personal';--> statement-breakpoint
PRAGMA optimize;
